function filter$thpkhTC1Select(p){
  this.constructor(p);
}
filter$thpkhTC1Select.prototype = new DirEvent();
filter$thpkhTC1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$thpkhTC1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_thuchien1','ngay_thuchien2', 'unit_id'], [p.options._ngay_thuchien1,p.options._ngay_thuchien2, p.options._unit_id]);
	dir$thpkhTC1SetMaster(p);

}

function dir$thpkhTC1SetMaster(p) {
  //p.request('ma_kh_request', '', ['id']);
}

filter$thpkhTC1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = dt.findRow("[so_luong0] > [sl_cl]");

  var fun = function(){
    dt.removeRow('[chon_yn] == 0'); 
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'chon_yn', 'chon_yn');
    pa.calcExpressionAll(0, 'chon_yn');
	//p.request('ma_kh_request', '', ['id']);
    //pa.appendForm(master, 0);
	p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();

    return false;
}









